create temporary view item_card_data_${grass_region_without_quote} as
SELECT
     'true' as is_item_card
    ,shop_id
    ,item_id
    ,model_id
    ,user_id
    ,is_ads
    ,source1_is_ads
    ,source2_is_ads
    ,feature_detail
    ,source1_feature_detail
    ,source2_feature_detail
    ,feature_group
    ,reporting_business_line
    ,reporting_module
    ,reporting_object
    ,source1_feature_group
    ,source1_reporting_business_line
    ,source1_reporting_module
    ,source1_reporting_object
    ,source2_feature_group
    ,source2_reporting_business_line
    ,source2_reporting_module
    ,source2_reporting_object
    ,if(spu_vsku_order_property.has_spu_vsku=true,spu_vsku_order_property.spu_vsku_item_id,null) as order_vsku_item_id
    ,if(click_spu_vsku_property.ctx_item_type=2,click_spu_vsku_property.spu_vsku_item_id,null)   as traffic_vsku_item_id


    ,sum(if(operation = 'omni_impression',operation_cnt,0))  AS imp_cnt
    ,sum(if(operation = 'omni_click' ,operation_cnt,0)) AS click_cnt
    ,sum(if(operation = 'order',operation_cnt,0)) AS order_cnt
    ,sum(if(operation = 'order',place_order_gmv,0)) AS gmv
    ,sum(if(operation = 'order',place_order_gmv_local,0)) AS gmv_local
    ,sum(if(operation = 'order',pc2_gmv,0)) AS pc2_gmv
    ,sum(if(operation = 'order',pc2_gmv_local,0)) AS pc2_gmv_local
    ,sum(if(operation = 'order',place_seller_gmv,0)) AS seller_gmv
    ,sum(if(operation = 'order',place_seller_gmv_local,0)) AS seller_gmv_local

    ,grass_region
    ,local_date
    ,local_hour
    ,regional_date
    ,regional_hour
    ,operation
FROM srdi_mart.dwd_sr_data_warehouse_platform
WHERE grass_region IN (${grass_region}) AND local_date = ${local_date} and operation in ('omni_impression','omni_click','order')
group by
     grass_region
    ,local_date
    ,local_hour
    ,regional_date
    ,regional_hour
    ,operation
    ,shop_id
    ,item_id
    ,model_id
    ,user_id
    ,is_ads
    ,source1_is_ads
    ,source2_is_ads
    ,feature_detail
    ,source1_feature_detail
    ,source2_feature_detail
    ,feature_group
    ,reporting_business_line
    ,reporting_module
    ,reporting_object
    ,source1_feature_group
    ,source1_reporting_business_line
    ,source1_reporting_module
    ,source1_reporting_object
    ,source2_feature_group
    ,source2_reporting_business_line
    ,source2_reporting_module
    ,source2_reporting_object
    ,if(spu_vsku_order_property.has_spu_vsku=true,spu_vsku_order_property.spu_vsku_item_id,null)
    ,if(click_spu_vsku_property.ctx_item_type=2,click_spu_vsku_property.spu_vsku_item_id,null)
;
