create temporary view omni_scenario_data_${grass_region_without_quote} as
SELECT
     shop_id
    ,item_id
    ,user_id
    ,cast(common_property.is_ads as boolean) as is_ads
    ,concat_ws(
         '-',
         array(
             page_type,
             page_section,
             target_type
         )
     ) AS original_feature_detail
    ,concat_ws(
         '-',
         array(
             mapped_page_type,
             page_section,
             target_type
         )
     ) AS feature_detail
    ,feature_group
    ,business_line
    ,module
    ,object

    ,grass_region
    ,grass_date as local_date
    ,Int(timestamp_timezone_convert(log_timestamp, grass_region, 'HH')) AS local_hour
    ,Date(timestamp_timezone_convert(log_timestamp, 'SG', 'yyyy-MM-dd')) AS regional_date
    ,Int(timestamp_timezone_convert(log_timestamp, 'SG', 'HH')) AS regional_hour
    ,event_type
FROM traffic_omni_oa.dwd_scenario_event_log_di__reg_sensitive_live
WHERE grass_region IN (${grass_region}) AND grass_date = ${local_date} and tz_type='local' and scenario_event_type in ('card_impression','card_click','button_click') and event_type in ('impression','click')
and (--S&R__ALL__ (for imp/click only SR has non-item-card,so only need to union sr.and for order ,will union in dws table)
   (business_line in ('Search') and module in ('Global Search', 'Image Search'))
   or
   (business_line in ('Homepage') and module in ('Daily Discover'))
   or
   (business_line in ('Rcmd') and module in ('User Scenario'))
   or--Search
   (business_line in ('Search') and module in ('Global Search'))
   or--Daily Discover
   (module in ('Daily Discover'))
   or--'You May Also Like'
   (object in ('you may also like'))
)
;
--sql_divide_splitter--

create temporary view non_item_card_data_${grass_region_without_quote} as
SELECT
     'false' as is_item_card
    ,shop_id
    ,item_id
    ,user_id
    ,is_ads
    ,feature_detail
    ,feature_group
    ,business_line
    ,module
    ,object
    ,sum(if(event_type = 'impression',1,0))  AS imp_cnt
    ,sum(if(event_type = 'click' ,1,0)) AS click_cnt

    ,grass_region
    ,local_date
    ,local_hour
    ,regional_date
    ,regional_hour
    ,event_type
FROM omni_scenario_data_${grass_region_without_quote}
where get_eventtype_and_cardtype(original_feature_detail,event_type)[1]='0' -- only collect non_item_cards
group by
     grass_region
    ,local_date
    ,local_hour
    ,regional_date
    ,regional_hour
    ,event_type
    ,shop_id
    ,item_id
    ,user_id
    ,is_ads
    ,feature_detail
    ,feature_group
    ,business_line
    ,module
    ,object
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dwm_sr_data_warehouse_tc_ab_all_cards partition(grass_region = ${grass_region}, local_date = ${local_date}, local_hour, regional_date, regional_hour, operation)
SELECT
     is_item_card
    ,shop_id
    ,item_id
    ,user_id
    ,null as request_id
    ,is_ads
    ,source1_is_ads
    ,source2_is_ads
    ,feature_detail
    ,source1_feature_detail
    ,source2_feature_detail
    ,imp_cnt
    ,click_cnt
    ,order_cnt
    ,gmv
    ,gmv_local
    ,pc2_gmv
    ,pc2_gmv_local
    ,feature_group
    ,reporting_business_line
    ,reporting_module
    ,reporting_object
    ,source1_feature_group
    ,source1_reporting_business_line
    ,source1_reporting_module
    ,source1_reporting_object
    ,source2_feature_group
    ,source2_reporting_business_line
    ,source2_reporting_module
    ,source2_reporting_object
    ,model_id
    ,null as exp_group_ids
    ,order_vsku_item_id
    ,traffic_vsku_item_id
    ,seller_gmv
    ,seller_gmv_local

    ,local_hour
    ,regional_date
    ,regional_hour
    ,operation
FROM item_card_data_${grass_region_without_quote}
union all
select
     is_item_card
    ,shop_id
    ,item_id
    ,user_id
    ,null as request_id
    ,is_ads
    ,null as source1_is_ads
    ,null as source2_is_ads
    ,feature_detail
    ,null as source1_feature_detail
    ,null as source2_feature_detail
    ,imp_cnt
    ,click_cnt
    ,0 as order_cnt
    ,0 as gmv
    ,0 as gmv_local
    ,0 as pc2_gmv
    ,0 as pc2_gmv_local
    ,feature_group
    ,business_line as reporting_business_line
    ,module as reporting_module
    ,object as reporting_object
    ,null as source1_feature_group
    ,null as source1_reporting_business_line
    ,null as source1_reporting_module
    ,null as source1_reporting_object
    ,null as source2_feature_group
    ,null as source2_reporting_business_line
    ,null as source2_reporting_module
    ,null as source2_reporting_object
    ,null as model_id
    ,null as exp_group_ids
    ,null as order_vsku_item_id
    ,null as traffic_vsku_item_id
    ,0 as seller_gmv
    ,0 as seller_gmv_local

    ,local_hour
    ,regional_date
    ,regional_hour
    ,case
       when event_type='impression' then 'omni_impression'
       when event_type='click' then 'omni_click'
       else event_type
      end as operation
from non_item_card_data_${grass_region_without_quote}
;
